import {form,text,area,select as sel,e,result,download} from '../ui.mjs';
import {vectorResult} from './vector.mjs';
import {pagesResult,svgTextLines} from './plus-svg.mjs';
import {recordForm} from './record-form.mjs';
import {inventory} from './plus-core.mjs';
import {cashFlowTool} from './plus-money.mjs';
import {table,exportCSV,need} from './shared.mjs';
const escapeVCF=value=>String(value).replace(/\\/g,'\\\\').replace(/\r\n|\r|\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');
export function makeVCard(v){return ['BEGIN:VCARD','VERSION:3.0','FN:'+escapeVCF(v.name),'N:'+escapeVCF(v.name)+';;;;','ORG:'+escapeVCF(v.company||''),'TITLE:'+escapeVCF(v.role||''),...(v.phone?['TEL;TYPE=CELL:'+escapeVCF(v.phone)]:[]),...(v.email?['EMAIL:'+escapeVCF(v.email)]:[]),...(v.website?['URL:'+escapeVCF(v.website)]:[]),'END:VCARD',''].join('\r\n');}
export function setupBusinessPlus(tool,mount,out){if(tool.id==='cash-flow')return cashFlowTool(mount,out);if(tool.id==='inventory-tracker')return inventoryTool(mount,out);if(tool.id==='shipping-label')return shipping(mount,out);return businessCard(mount,out);}
function businessCard(mount,out){let disposed=false;form(mount,[text('name','Name','Alex Rana'),text('role','Role / title','Designer'),text('company','Company / brand','A little studio'),{...text('phone','Phone','+977 9800000000'),required:false},{...text('email','Email','hello@example.com','email'),required:false},{...text('website','Website','https://example.com','url'),required:false},text('accent','Accent color','#2c6550','color'),sel('qr','Contact QR code',[['yes','Include vCard QR'],['no','No QR']],'yes')],async v=>{need(v.name.length<=40&&v.role.length<=50&&v.company.length<=50&&v.phone.length<=30&&v.email.length<=70&&v.website.length<=100,'Use concise card details: name 40, role/company 50, phone 30, email 70 and website 100 characters.');const vcf=makeVCard(v);let code='';if(v.qr==='yes'){const {default:qrcode}=await import('../assets/vendor/qrcode.mjs');qrcode.stringToBytes=s=>Array.from(new TextEncoder().encode(s));const qr=qrcode(0,'M');qr.addData(vcf,'Byte');qr.make();const svg=qr.createSvgTag({cellSize:4,margin:16,scalable:true}).replace('<svg ','<svg x="606" y="175" width="198" height="198" ');code=svg;}if(disposed)return;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="850" height="550" viewBox="0 0 850 550" role="img" aria-label="Business card"><rect width="850" height="550" fill="#fffef8"/><rect width="22" height="550" fill="${e(v.accent)}"/><circle cx="771" cy="32" r="116" fill="${e(v.accent)}" opacity=".09"/><g font-family="Arial,sans-serif" fill="#253c31"><text x="58" y="82" font-size="20" letter-spacing="2">${e(v.company.toUpperCase())}</text><text x="58" y="203" font-size="42" font-weight="700" textLength="${Math.min(520,v.name.length*24)}" lengthAdjust="spacingAndGlyphs">${e(v.name)}</text><text x="58" y="249" font-size="22" textLength="${Math.min(500,v.role.length*12)}" lengthAdjust="spacingAndGlyphs" fill="${e(v.accent)}">${e(v.role)}</text>${[v.phone,v.email,v.website].filter(Boolean).map((value,i)=>`<text x="58" y="${340+i*43}" font-size="19" textLength="${Math.min(510,value.length*10.5)}" lengthAdjust="spacingAndGlyphs">${e(value)}</text>`).join('')}</g>${code}</svg>`;pagesResult(out,[svg],'nepocore-business-card',{width:850,height:550,paper:{widthMM:85,heightMM:55},details:[['Physical card','85 × 55 mm']],note:'Check spelling and scan the contact QR before printing. Downloading a vCard does not send an email or modify an address book.'});const b=document.createElement('button');b.className='btn secondary small';b.textContent='Download contact VCF';b.onclick=()=>download(new Blob([vcf],{type:'text/vcard;charset=utf-8'}),'nepocore-contact.vcf');out.querySelector('.result-actions').append(b);},{label:'Create business card'});return()=>{disposed=true;};}
function inventoryTool(mount,out){return recordForm(mount,{columns:[{id:'sku',label:'SKU'},{id:'name',label:'Item'},{id:'quantity',label:'Quantity',type:'number',min:0,max:1000000,step:1},{id:'cost',label:'Unit cost',type:'number',min:0,max:1000000},{id:'reorder',label:'Reorder at',type:'number',min:0,max:1000000,step:1}],initial:[{sku:'NOTE-A',name:'Notebook',quantity:12,cost:80,reorder:5},{sku:'PEN-B',name:'Pen',quantity:4,cost:20,reorder:5},{sku:'BAG-C',name:'Bag',quantity:3,cost:450,reorder:2}],fields:[sel('currency','Currency',['NPR','USD','EUR','INR'],'NPR')],saveKey:'nepocore-inventory-v1',label:'Update inventory summary',note:'Edit quantities to reflect a manual count. Optional browser storage is not a shared or permanent inventory database; export backups.',run:(data,v)=>{const list=inventory(data.map(r=>[r.sku,r.name,r.quantity,r.cost,r.reorder].join('|')).join('\n'));need(new Set(list.map(r=>r.sku)).size===list.length,'Use a unique SKU for every item.');const total=list.reduce((s,r)=>s+r.value,0);need(Number.isSafeInteger(total),'The stock value is too large for exact minor-unit arithmetic.');result(out,{label:'Recorded stock value',value:v.currency+' '+(total/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}),details:[['Items',list.length],['At/below reorder level',list.filter(r=>r.low).length]],html:table(['SKU','Item','Quantity','Unit cost','Value','Reorder'],list.map(r=>[r.sku,r.name,r.quantity,(r.cost/100).toFixed(2),(r.value/100).toFixed(2),r.low?'Review stock':'Above threshold']))});exportCSV(out,list.map(r=>({...r,cost:r.cost/100,value:r.value/100,currency:v.currency})),'nepocore-inventory.csv');}});}
function shipping(mount,out){return form(mount,[area('sender','Sender address','A Little Studio\nKathmandu\nNepal'),area('recipient','Recipient address','Sample Recipient\nStreet and building\nCity, postal code\nCountry'),{...text('reference','Package reference','ORDER-001'),required:false},{...text('notes','Delivery notes','','text',true),required:false},sel('paper','Output size',[['label','100 × 150 mm label'],['four','4 × 6 inch label'],['a4','A4 sheet'],['letter','US Letter']],'label')],v=>{need(v.sender.length<=220&&v.recipient.length<=300&&v.reference.length<=40&&v.notes.length<=140,'Keep addresses and notes concise for a readable label.');const senderLines=v.sender.split('\n').flatMap(s=>svgTextLines(s,40)),recipientLines=v.recipient.split('\n').flatMap(s=>svgTextLines(s,32));need(senderLines.length<=5&&recipientLines.length<=10,'Use up to 5 wrapped sender lines and 10 wrapped recipient lines so every address line is visible.');const dimensions=v.paper==='label'?{widthMM:100,heightMM:150}:v.paper==='four'?{widthMM:101.6,heightMM:152.4}:v.paper==='letter'?{widthMM:215.9,heightMM:279.4}:{widthMM:210,heightMM:297},W=Math.round(dimensions.widthMM*6),H=Math.round(dimensions.heightMM*6),labelW=600,labelH=900,x=(W-labelW)/2,y=(H-labelH)/2;let body=`<rect x="${x+2}" y="${y+2}" width="596" height="896" rx="9" fill="white" stroke="#253c31" stroke-width="2"/><g transform="translate(${x} ${y})" font-family="Arial,sans-serif" fill="#253c31"><text x="35" y="48" font-size="16" font-weight="700">ADDRESS LABEL · NO POSTAGE</text><path d="M35 68H565" stroke="#9cae9f"/><text x="35" y="104" font-size="14">FROM</text>`;let py=137;for(const line of senderLines){body+=`<text x="35" y="${py}" font-size="19">${e(line)}</text>`;py+=26;}body+='<path d="M35 291H565" stroke="#9cae9f"/><text x="35" y="329" font-size="17" font-weight="700">DELIVER TO</text>';py=378;for(const line of recipientLines){body+=`<text x="35" y="${py}" font-size="27">${e(line)}</text>`;py+=35;}body+=`<path d="M35 756H565" stroke="#9cae9f"/><text x="35" y="792" font-size="20">Reference: ${e(v.reference)}</text>`;svgTextLines(v.notes,54).slice(0,3).forEach((line,i)=>body+=`<text x="35" y="${827+i*20}" font-size="15">${e(line)}</text>`);body+='</g>';const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Address label"><rect width="100%" height="100%" fill="white"/>${body}</svg>`;pagesResult(out,[svg],'nepocore-address-label',{width:W,height:H,paper:dimensions,note:'This is an address label only: no postage, tracking service or customs declaration is purchased or created. Review every address line before printing.'});},{label:'Create address label'});}
